from taf.gnb.oam.coam.cu.schemas.base import SchemaField, SchemaObject


class DistNameSlot(SchemaObject):
    config = SchemaField(name="config", optional=True)
    runtime = SchemaField(name="runtime", optional=True)

    def __init__(self, config, runtime):
        self.config = config
        self.runtime = runtime

        super(DistNameSlot, self).__init__()


class Alarms(SchemaObject):
    uuid = SchemaField(name="uuid", not_null=True)
    severity = SchemaField(name="severity", not_null=True)
    alarm_id = SchemaField(name="alarmId", not_null=True)
    alarm_name = SchemaField(name="alarmName", not_null=True)
    fault_id = SchemaField(name="faultId", not_null=True)
    fault_name = SchemaField(name="faultName", not_null=True)

    def __init__(self, uuid, severity, alarm_id, alarm_name, fault_id, fault_name):
        self.uuid = uuid
        self.severity = severity
        self.alarm_id = alarm_id
        self.alarm_name = alarm_name
        self.fault_id = fault_id
        self.fault_name = fault_name

        super(Alarms, self).__init__()


class BasicCellSlot(SchemaObject):
    id = SchemaField(name="id", not_null=True)
    administrative_state = SchemaField(name="administrativeState", not_null=True)
    operational_state = SchemaField(name="operationalState", not_null=True)
    cell_group_id = SchemaField(name="cellGroupId", not_null=True)
    cell_name = SchemaField(name="cellName")
    dist_names = SchemaField(name="distNames", klass=DistNameSlot, not_null=True)
    technology = SchemaField(name="technology", not_null=True)
    physical_layer_cell_id = SchemaField(name='physicalLayerCellID', not_null=True)
    nr_cell_identity = SchemaField(name='nrCellIdentity', not_null=True)
    name = SchemaField(name='name', not_null=True)
    blocking_state = SchemaField(name='blockingState', optional=True)
    nrarfcn = SchemaField(name='nrarfcn', optional=True)
    nrarfcn_dl = SchemaField(name="nrarfcnDl", optional=True)
    nrarfcn_ul = SchemaField(name="nrarfcnUl", optional=True)
    alarms = SchemaField(name="alarms", klass=Alarms, many=True, not_null=True)

    def __init__(self, id, administrative_state, operational_state, cell_group_id, cell_name, dist_names, technology,
                 physical_layer_cell_id, nr_cell_identity, name, blocking_state, nrarfcn, nrarfcn_dl, nrarfcn_ul, alarms):
        self.id = id
        self.administrative_state = administrative_state
        self.operational_state = operational_state
        self.cell_group_id = cell_group_id
        self.cell_name = cell_name
        self.dist_names = dist_names
        self.technology = technology
        self.physical_layer_cell_id = physical_layer_cell_id
        self.nr_cell_identity = nr_cell_identity
        self.name = name
        self.blocking_state = blocking_state
        self.nrarfcn = nrarfcn
        self.nrarfcn_dl = nrarfcn_dl
        self.nrarfcn_ul = nrarfcn_ul
        self.alarms = alarms

        super(BasicCellSlot, self).__init__()


class CellSlot(SchemaObject):
    basic_cell = SchemaField(name="basicCell", klass=BasicCellSlot, not_null=True)
    nr_du_id = SchemaField(name="nrDuId", not_null=True)
    du_name = SchemaField(name='duName')

    def __init__(self, basic_cell, nr_du_id, du_name):
        self.basic_cell = basic_cell
        self.nr_du_id = nr_du_id
        self.du_name = du_name

        super(CellSlot, self).__init__()


class GetCellsStatusesv1(SchemaObject):
    created = SchemaField(name="created", klass=CellSlot, many=True)

    def __init__(self, created):
        if created:
            self.created = created
        else:
            self.created = []

        super(GetCellsStatusesv1, self).__init__()
